package com.drogaria.backend.controller;
import com.drogaria.backend.dto.EnderecoRequest; import com.drogaria.backend.entity.Endereco; import com.drogaria.backend.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/endereco") public class EnderecoController { private final EnderecoService s; private final CarrinhoService a; public EnderecoController(EnderecoService s,CarrinhoService a){this.s=s;this.a=a;} @PostMapping public ResponseEntity<Endereco> salvar(@Valid @RequestBody EnderecoRequest r,Authentication x){a.validarAcesso(r.getIdCliente(),x);return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @GetMapping("/cliente/{id}") public List<Endereco> cliente(@PathVariable Integer id,Authentication x){a.validarAcesso(id,x);return s.cliente(id);} @GetMapping("/{id}") public Endereco buscar(@PathVariable Integer id){return s.buscar(id);} @PutMapping("/{id}") public Endereco atualizar(@PathVariable Integer id,@Valid @RequestBody EnderecoRequest r){return s.atualizar(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Integer id){s.excluir(id);return ResponseEntity.noContent().build();} }